-- 80 Treasure Isle: the explorer walks his loop and asks the island what
-- is under him - the tileset's `data` (Tilemap.get_tile_data) - and lava
-- burns. The chests he opens were tiles until the scene loaded (`spawns`).
-- Generated by tools/gen_scenes.py.

script = { tick_rate = 60 }

local nav = require("nav")
local SCENE = "scenes/80-treasure-isle.scene"
local captions = true
local isle, explorer, smoke, coins, status
local chests, opened = {}, {}
local found, heat = 0, 0

function init(entity)
    isle = Entity.find_by_name("Isle")
    explorer = Entity.find_by_name("Explorer")
    smoke = Entity.find_by_name("Smoke")
    coins = Entity.find_by_name("Coins")
    status = Entity.find_by_name("Status")
    chests = Entity.find_by_tag("chest")
end

function update(entity, dt)
    nav.tick(SCENE)
    if Input.is_key_just_pressed("Tab") then captions = nav.toggle_ui_captions(captions) end
    local x, y = Transform.get_position(explorer)
    local cx, cy = Tilemap.world_to_tile(isle, x, y)
    local kind = Tilemap.get_tile_data(isle, "ground", cx, cy, "kind") or "?"
    local burns = Tilemap.get_tile_data(isle, "ground", cx, cy, "burns") == true
    -- Lava burns: he glows red and smokes while on it, and cools after.
    heat = math.max(0, math.min(1, heat + (burns and dt * 2 or -dt * 1.2)))
    Sprite.set_color(explorer, 1, 1 - heat * 0.6, 1 - heat * 0.7, 1)
    Transform.set_position(smoke, x, y + 10)
    Particles.set_rate(smoke, burns and 26 or 0)
    -- Chests: the tiles that became prefabs. Walk past one to open it.
    for i, c in ipairs(chests) do
        if not opened[i] then
            local px, py = Transform.get_position(c)
            if (px - x) ^ 2 + (py - y) ^ 2 < 75 * 75 then
                opened[i] = true
                found = found + 1
                Transform.set_position(coins, px, py)
                Particles.emit_burst(coins, 40)
                Sprite.set_color(c, 0.55, 0.5, 0.45, 1)
            end
        end
    end
    if found == #chests and #chests > 0 then
        -- Every chest open: shut them again for the next lap.
        local far = true
        for i, c in ipairs(chests) do
            local px, py = Transform.get_position(c)
            if (px - x) ^ 2 + (py - y) ^ 2 < 160 * 160 then far = false end
        end
        if far then
            for i, c in ipairs(chests) do opened[i] = false; Sprite.set_color(c, 1, 1, 1, 1) end
            found = 0
        end
    end
    UI.set_text(status, "underfoot: " .. kind .. (burns and " - it burns!" or "") .. "   chests " .. found .. " / " .. #chests)
end
